//     println("        gd = " + typeToString(gd))
//     println("        hd = " + typeToString(hd))
//     println("        md = " + typeToString(md))
    val result = sa.equivalentED(fd, md)
    if (debug) {
       println("isMeet: fd = " + typeToString(fd))
       println("        gd = " + typeToString(gd))
       println("        hd = " + typeToString(hd))
       println("        md = " + typeToString(md))
       println(result)
    }
//     println("    result = " + result)
    result
  }

